import {t,label,ui,markup,setText} from './language.mjs';
import {AccountStore,api} from './accounts.mjs';
import {updateMaternalRequirements} from './forms.mjs';
import {maternalInputs} from './family-ui.mjs';
import {createPatientDirectory} from './directory-ui.mjs';
const $=s=>document.querySelector(s);
export function setupAccounts(onChange){
 const view=document.createElement('section');view.id='auth-view';view.hidden=true;
 view.innerHTML=ui`<header class="wrap site-header"><a class="brand" href="#home"><img src="assets/icon.svg" width="42" height="42" alt=""><span>E-Nay<small>CARE, CLOSER TO HOME</small></span></a><a class="text-link" href="#home">Back to home ↗</a></header><main id="auth-main" class="auth-layout wrap" tabindex="-1"><div class="auth-story"><p class="eyebrow">KASAMA MO SA PAG-AALAGA.</p><h1><span lang="fil">Tuloy po.</span><br><em>Your care starts here.</em></h1><p>Mothers manage their own care record and their children’s records. Fathers can view shared records through an invitation from the mother. Health workers verify requests, approve appointments and record administered doses.</p><img src="assets/philippines-mother-child-small.webp" width="600" height="540" alt="A mother carrying her child at a viewpoint in Cagayan Valley, Philippines"><p class="data-note">On a shared device, always sign out. Your saved offline copy stays encrypted until you unlock it.</p></div><section class="panel auth-panel"><div class="auth-tabs" role="group" aria-label="Account action"><button class="button primary" id="choose-login" aria-pressed="true" type="button">Sign in</button><button class="button secondary" id="choose-register" aria-pressed="false" type="button">Create patient account</button></div><h2 id="auth-title">Welcome back.</h2><p id="auth-intro">Your barangay health worker can help you get started. Sign in to see your family’s records, or create a patient account. You can also unlock a saved copy when offline.</p><form id="auth-form"><div id="registration-name" hidden><label for="account-name">Your name</label><input id="account-name" autocomplete="name" maxlength="80"><label for="account-kind">I am a</label><select id="account-kind" name="kind"><option value="mother">Mother</option><option value="father">Father / companion</option></select><div id="registration-maternal">${maternalInputs('join')}</div><p class="data-note">A mother account includes one personal maternal record. A father account starts with a pairing code from the mother.</p></div><label for="account-username">Username</label><input id="account-username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="40" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}" required><p class="hint">3–40 letters, numbers, periods, underscores or hyphens.</p><label for="account-password">Password</label><input id="account-password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required><p class="hint">At least 12 characters. Your password is never saved on this device.</p><p id="auth-error" class="notice warning" role="alert" hidden></p><p id="auth-success" class="notice good" role="status" hidden></p><button id="auth-submit" class="button primary" type="submit">Sign in / unlock offline copy ↗</button></form><p class="data-note">Staff access is approved by the clinic. Already have a clinic record? Ask your health worker to link it to an existing account before setting up your personal profile.</p></section></main>`;
 document.body.insertBefore(view,$('#workspace-view'));
 const resumeStatus=document.createElement('p');resumeStatus.id='auth-resume';resumeStatus.className='notice good';resumeStatus.setAttribute('role','status');setText(resumeStatus,'Restoring your session…');$('.auth-panel').prepend(resumeStatus);
 function busy(value){$('#auth-main').setAttribute('aria-busy',String(value));$('#auth-form').hidden=value;$('.auth-tabs').hidden=value;resumeStatus.hidden=!value;for(const control of view.querySelectorAll('input,button,select'))control.disabled=value;if(!value)registrationFields();}
 busy(true);
 let registration=false;
 function registrationFields(){$('#account-kind').required=registration;$('#account-kind').disabled=!registration;const mother=registration&&$('#account-kind').value==='mother';$('#registration-maternal').hidden=!mother;for(const c of $('#registration-maternal').querySelectorAll('input,select'))c.disabled=!mother;updateMaternalRequirements($('#auth-form'));}
 $('#account-kind').onchange=registrationFields;$('#join-pregnancy').onchange=()=>updateMaternalRequirements($('#auth-form'));
 function mode(value){registration=value;registrationFields();for(const [id,active] of [['choose-login',!value],['choose-register',value]]){const tab=$('#'+id);tab.classList.toggle('primary',active);tab.classList.toggle('secondary',!active);tab.setAttribute('aria-pressed',String(active));}$('#registration-name').hidden=!value;$('#account-name').required=value;setText($('#auth-title'),value?'A little closer to your care.':'Welcome back.');$('#account-password').autocomplete=value?'new-password':'current-password';setText($('#auth-submit'),value?'Create patient account ↗':'Sign in / unlock offline copy ↗');$('#auth-error').hidden=true;$('#auth-success').hidden=true;updateMaternalRequirements($('#auth-form'));}
 $('#choose-login').onclick=()=>mode(false);$('#choose-register').onclick=()=>mode(true);
 $('#auth-form').onsubmit=async event=>{event.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').hidden=true;$('#auth-success').hidden=true;
  try{const username=$('#account-username').value,password=$('#account-password').value;
   if(registration){await api('register',{method:'POST',body:{username,password,displayName:$('#account-name').value,kind:$('#account-kind').value,...Object.fromEntries(new FormData($('#auth-form')))}});mode(false);const store=await AccountStore.signIn(username,password);$('#account-password').value='';mode(false);onChange(store);}
   else{const store=await AccountStore.signIn(username,password);$('#account-password').value='';onChange(store);}
  }catch(error){setText($('#auth-error'),error.message);$('#auth-error').hidden=false;}
  finally{button.disabled=false;}
 };
 return {show(){view.hidden=false;},hide(){view.hidden=true;},reset(){mode(false);$('#account-password').value='';},async restore(){try{const store=await AccountStore.resume();if(store)onChange(store);}catch(error){setText($('#auth-error'),error.message);$('#auth-error').hidden=false;}finally{busy(false);}}};
}
export async function patientAccess(store){
 const {accounts}=await api('accounts',{proof:store.proof});
 return createPatientDirectory(accounts,[...store.data.mothers,...store.data.children],(accountId,patientIds)=>api('links',{method:'PUT',proof:store.proof,body:{accountId,patientIds}}));
}
